from pathlib import Path
import re

ROOT = Path("app/src/main/java/com/abhijit/gamesolution")

# The base FloatingService is generated by prepare_bubble.py. Keep all secondary-bubble
# settings in this post-generation patch so the generated source always gets the same UI.
p = ROOT / "FloatingService.java"
s = p.read_text(encoding="utf-8")

if "Recent App Bubble" not in s:
    marker = '  TextView snap=label("Snap to Edge: "+(BubbleSettings.isSnapToEdge(this)?"ON":"OFF"),14,text,Typeface.BOLD);'
    if marker not in s:
        raise SystemExit("Bubble settings snap marker not found")
    block = '''  TextView recentTitle=label("Recent App Bubble: "+(BubbleSettings.isRecentAppBubbleEnabled(this)?"ON":"OFF"),14,text,Typeface.BOLD);\n  recentTitle.setGravity(Gravity.CENTER_VERTICAL);recentTitle.setPadding(dp(12),0,dp(12),0);recentTitle.setBackground(round(Color.rgb(38,46,66),14));\n  recentTitle.setOnClickListener(v->{boolean n=!BubbleSettings.isRecentAppBubbleEnabled(this);BubbleSettings.setRecentAppBubbleEnabled(this,n);recentTitle.setText("Recent App Bubble: "+(n?"ON":"OFF"));restartSecondaryBubbleService();});\n  box.addView(recentTitle,rowLp(dp(48),dp(8)));\n  TextView recentTransparency=label("Recent Bubble Transparency: "+BubbleSettings.getRecentTransparency(this)+"%",14,text,Typeface.BOLD);box.addView(recentTransparency);\n  SeekBar recentTransparencyBar=new SeekBar(this);recentTransparencyBar.setMax(80);recentTransparencyBar.setProgress(BubbleSettings.getRecentTransparency(this)-20);box.addView(recentTransparencyBar,rowLp(-2,dp(10)));\n  recentTransparencyBar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar bar,int progress,boolean fromUser){int n=20+progress;recentTransparency.setText("Recent Bubble Transparency: "+n+"%");BubbleSettings.setRecentTransparency(FloatingService.this,n);restartSecondaryBubbleService();}public void onStartTrackingTouch(SeekBar bar){}public void onStopTrackingTouch(SeekBar bar){}});\n  TextView activityTitle=label("Activity Bubble: "+(BubbleSettings.isActivitySwitchBubbleEnabled(this)?"ON":"OFF"),14,text,Typeface.BOLD);\n  activityTitle.setGravity(Gravity.CENTER_VERTICAL);activityTitle.setPadding(dp(12),0,dp(12),0);activityTitle.setBackground(round(Color.rgb(38,46,66),14));\n  activityTitle.setOnClickListener(v->{boolean n=!BubbleSettings.isActivitySwitchBubbleEnabled(this);BubbleSettings.setActivitySwitchBubbleEnabled(this,n);activityTitle.setText("Activity Bubble: "+(n?"ON":"OFF"));restartSecondaryBubbleService();});\n  box.addView(activityTitle,rowLp(dp(48),dp(8)));\n  TextView activityTransparency=label("Activity Bubble Transparency: "+BubbleSettings.getActivityTransparency(this)+"%",14,text,Typeface.BOLD);box.addView(activityTransparency);\n  SeekBar activityTransparencyBar=new SeekBar(this);activityTransparencyBar.setMax(80);activityTransparencyBar.setProgress(BubbleSettings.getActivityTransparency(this)-20);box.addView(activityTransparencyBar,rowLp(-2,dp(10)));\n  activityTransparencyBar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar bar,int progress,boolean fromUser){int n=20+progress;activityTransparency.setText("Activity Bubble Transparency: "+n+"%");BubbleSettings.setActivityTransparency(FloatingService.this,n);restartSecondaryBubbleService();}public void onStartTrackingTouch(SeekBar bar){}public void onStopTrackingTouch(SeekBar bar){}});\n\n'''
    s = s.replace(marker, block + marker, 1)

if "void restartSecondaryBubbleService()" not in s:
    marker = " private void openMenu("
    if marker not in s:
        raise SystemExit("openMenu marker not found")
    helper = ''' private void restartSecondaryBubbleService(){try{Intent i=new Intent(this,SecondaryBubbleService.class);if(Build.VERSION.SDK_INT>=Build.VERSION_CODES.O)startForegroundService(i);else startService(i);}catch(Exception ignored){}}\n'''
    s = s.replace(marker, helper + marker, 1)

# The main bubble dialog must represent the actual current eligible foreground app.
# The Recent App row separately excludes targetPackage, so it will show the previous apps.
s = s.replace(
    'targetPackage=ForegroundAppResolver.getPreviousPackage(this,getPackageName());',
    'targetPackage=ForegroundAppResolver.getCurrentPackage(this,getPackageName());',
    1
)

p.write_text(s, encoding="utf-8")
print("Secondary bubble settings patched into generated FloatingService")
